import bpy, json, math
from mathutils import Vector

L = json.load(open("inputs/layout.json"))
MM = 0.001

def wbbox(o):
    cs = [o.matrix_world @ Vector(p) for p in o.bound_box]
    return Vector(map(min, cs)), Vector(map(max, cs))

def bb_from(a0,a1,b0,b1,c0,c1):
    return Vector((a0,b0,c0)), Vector((a1,b1,c1))

groups = {}
for o in bpy.data.objects:
    for p in ("Rack_", "Containment_", "PerfTile_", "CableTray_"):
        if o.name.startswith(p):
            groups.setdefault(p, []).append(o)
for k in sorted(groups):
    print(k, len(groups[k]), sorted(o.name for o in groups[k])[:20])

# ---- racks vs layout
print("\n-- rack check --")
bad = 0
for r in L["racks"]:
    o = bpy.data.objects.get("Rack_" + r["id"])
    if o is None:
        print("MISSING", r["id"]); bad += 1; continue
    mn, mx = wbbox(o)
    cx, cy = r["center"][0]*MM, r["center"][1]*MM
    w, d = r["size"][0]*MM, r["size"][1]*MM
    exp = {
        "x": (round(cx-w/2,4), round(cx+w/2,4)),
        "y": (round(cy-d/2,4), round(cy+d/2,4)),
        "z": (0.6, 2.6),
    }
    got = ((round(mn.x,4), round(mx.x,4)), (round(mn.y,4), round(mx.y,4)), (round(mn.z,4), round(mx.z,4)))
    okx = abs(got[0][0]-exp["x"][0]) < 0.02 and abs(got[0][1]-exp["x"][1]) < 0.02
    oky = abs(got[1][0]-exp["y"][0]) < 0.02 and abs(got[1][1]-exp["y"][1]) < 0.02
    okz = abs(got[2][0]-0.6) < 0.005
    prop = o.get("rackId")
    if not (okx and oky and okz and prop == r["id"]):
        print("PROBLEM", r["id"], "expected", exp, "got", got, "rackId", prop); bad += 1
print("rack problems:", bad)
print("rack loc/rot sample:", [(o.name, tuple(round(v,3) for v in o.location),
      tuple(round(v,1) for v in o.rotation_euler), o["rackId"]) for o in sorted(groups["Rack_"], key=lambda o:o.name)][:4])

# ---- collisions
print("\n-- collisions --")
def overlap(a, b, eps=1e-4):
    return (a[0].x < b[1].x-eps and a[1].x > b[0].x+eps and
            a[0].y < b[1].y-eps and a[1].y > b[0].y+eps and
            a[0].z < b[1].z-eps and a[1].z > b[0].z+eps)
rbs = {o.name: wbbox(o) for o in groups["Rack_"]}
names = sorted(rbs)
hits = []
for i in range(len(names)):
    for j in range(i+1, len(names)):
        if overlap(rbs[names[i]], rbs[names[j]]):
            hits.append((names[i], names[j]))
print("rack-rack overlaps:", hits)

shell = {}
for o in bpy.data.objects:
    if o.name.startswith(("Wall_", "Column_")):
        shell[o.name] = wbbox([o])
for rn, rb in rbs.items():
    for sn, sb in shell.items():
        if overlap(rb, sb):
            print("RACK/SHELL OVERLAP", rn, sn)
print("shell objects checked:", len(shell))

# ---- containment
print("\n-- containment --")
cold = [a for a in L["aisles"] if a["type"] == "cold"][0]
x0,y0,x1,y1 = [v*MM for v in cold["rect"]]
for o in sorted(groups["Containment_"], key=lambda o:o.name):
    mn, mx = wbbox(o)
    print(o.name, [round(v,3) for v in mn], [round(v,3) for v in mx])
print("cold aisle rect", x0,y0,x1,y1, "rack top 2.6")

# ---- perf tiles
print("\n-- perf tiles --")
exp_cells = []
for i in range(int(x0/0.6), int(x1/0.6)):
    for j in range(int(y0/0.6), int(y1/0.6)+1):
        if (j+1)*0.6 <= y1 + 1e-9:
            exp_cells.append((i, j))
print("expected cells:", len(exp_cells))
got = set()
tops = set()
for o in groups["PerfTile_"]:
    mn, mx = wbbox(o)
    tops.add((round(mn.z,4), round(mx.z,4)))
    got.add((int(round((mn.x+mx.x)/2/0.6 - 0.5)), int(round((mn.y+mx.y)/2/0.6 - 0.5))))
    dimx, dimy = round(mx.x-mn.x,4), round(mx.y-mn.y,4)
    if abs(dimx-0.6) > 0.002 or abs(dimy-0.6) > 0.002:
        print("BAD TILE SIZE", o.name, dimx, dimy)
print("tile z spans:", tops)
print("tiles match expected cells:", got == set(exp_cells), len(got))
print("missing:", sorted(set(exp_cells)-got), "extra:", sorted(got-set(exp_cells)))

# ---- cable trays
print("\n-- cable trays --")
for o in sorted(groups["CableTray_"], key=lambda o:o.name):
    mn, mx = wbbox(o)
    print(o.name, [round(v,3) for v in mn], [round(v,3) for v in mx],
          "width", round(mx.y-mn.y,3), "bottom", round(mn.z,3))
print("\ntotal objects:", len(bpy.data.objects))
